-- ═════════════════════════════════════════════════════════════════════════════════════════════
-- Hand-written part (Prisma cannot express it): RLS, partial unique indexes, exclusion constraint, triggers, CHECKs.
-- Constraint, index and trigger names below are part of the migration contract (tests/db/phase4-schema.test.ts).
-- ═════════════════════════════════════════════════════════════════════════════════════════════

CREATE EXTENSION IF NOT EXISTS btree_gist;

-- ───────────── Row-level security ─────────────
-- Same fail-closed DO-block as Phase 1-3: every table with a "tenantId" column (the 13 new ones included)
-- is ENABLEd + FORCEd and gets the tenant_isolation policy. Re-running it is idempotent.
DO $$
DECLARE
  t record;
BEGIN
  FOR t IN
    SELECT c.table_name
    FROM information_schema.columns c
    JOIN information_schema.tables tb
      ON tb.table_schema = c.table_schema AND tb.table_name = c.table_name AND tb.table_type = 'BASE TABLE'
    WHERE c.table_schema = 'public' AND c.column_name = 'tenantId'
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t.table_name);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t.table_name);
    EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %I', t.table_name);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I USING ("tenantId" = (SELECT NULLIF(current_setting(''app.tenant_id'', true), ''''))) WITH CHECK ("tenantId" = (SELECT NULLIF(current_setting(''app.tenant_id'', true), '''')))',
      t.table_name
    );
  END LOOP;
END
$$;

-- ───────────── Generic guards (reused by several tables below) ─────────────
-- Rejects an UPDATE that changes any column named in the trigger arguments.
CREATE OR REPLACE FUNCTION leadro_immutable_columns() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  i int;
BEGIN
  FOR i IN 0 .. TG_NARGS - 1 LOOP
    IF to_jsonb(OLD) -> TG_ARGV[i] IS DISTINCT FROM to_jsonb(NEW) -> TG_ARGV[i] THEN
      RAISE EXCEPTION '%.% is immutable', TG_TABLE_NAME, TG_ARGV[i]
        USING ERRCODE = 'restrict_violation';
    END IF;
  END LOOP;
  RETURN NEW;
END
$$;

-- Rejects a "status" change that is not listed as 'FROM>TO' in the trigger arguments.
CREATE OR REPLACE FUNCTION leadro_status_transitions() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  old_status text := to_jsonb(OLD) ->> 'status';
  new_status text := to_jsonb(NEW) ->> 'status';
BEGIN
  IF old_status IS DISTINCT FROM new_status AND NOT ((old_status || '>' || new_status) = ANY (TG_ARGV)) THEN
    RAISE EXCEPTION '% status transition % -> % is not allowed', TG_TABLE_NAME, old_status, new_status
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END
$$;

-- Financial records are never deleted (a correction is a new record).
CREATE OR REPLACE FUNCTION leadro_no_delete() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '% rows are never deleted', TG_TABLE_NAME
    USING ERRCODE = 'restrict_violation';
END
$$;

-- ───────────── Append-only: ledger and approval decisions ─────────────
-- leadro_append_only() was created in the Phase 2 migration.
CREATE TRIGGER ledger_entry_no_update_delete
  BEFORE UPDATE OR DELETE ON "LedgerEntry"
  FOR EACH ROW EXECUTE FUNCTION leadro_append_only();
CREATE TRIGGER ledger_entry_no_truncate
  BEFORE TRUNCATE ON "LedgerEntry"
  FOR EACH STATEMENT EXECUTE FUNCTION leadro_append_only();

CREATE TRIGGER approval_decision_no_update_delete
  BEFORE UPDATE OR DELETE ON "ApprovalDecision"
  FOR EACH ROW EXECUTE FUNCTION leadro_append_only();
CREATE TRIGGER approval_decision_no_truncate
  BEFORE TRUNCATE ON "ApprovalDecision"
  FOR EACH STATEMENT EXECUTE FUNCTION leadro_append_only();

-- ───────────── Ledger: a reversal mirrors exactly one earlier entry ─────────────
-- The CHECKs below cover the row alone; this trigger checks the row against the entry it reverses. A second reversal of the
-- same entry is rejected by the unique index ledger_entry_one_reversal.
CREATE OR REPLACE FUNCTION leadro_ledger_entry_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  orig "LedgerEntry"%ROWTYPE;
BEGIN
  IF NEW."reversesEntryId" IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT * INTO orig FROM "LedgerEntry" WHERE "id" = NEW."reversesEntryId" AND "tenantId" = NEW."tenantId";
  IF NOT FOUND THEN
    RAISE EXCEPTION 'reversed ledger entry % does not exist', NEW."reversesEntryId" USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF orig."type" = 'REVERSAL' THEN
    RAISE EXCEPTION 'a reversal cannot itself be reversed; post a new entry instead' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."amountMinor" <> -orig."amountMinor" OR NEW."currency" <> orig."currency" THEN
    RAISE EXCEPTION 'a reversal must be the exact negative of the entry it reverses (same currency)' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."jobId" IS DISTINCT FROM orig."jobId" OR NEW."customerId" IS DISTINCT FROM orig."customerId" THEN
    RAISE EXCEPTION 'a reversal must refer to the same job and customer as the entry it reverses' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER ledger_entry_guard
  BEFORE INSERT ON "LedgerEntry"
  FOR EACH ROW EXECUTE FUNCTION leadro_ledger_entry_guard();

CREATE UNIQUE INDEX ledger_entry_one_reversal
  ON "LedgerEntry" ("tenantId", "reversesEntryId") WHERE "reversesEntryId" IS NOT NULL;

ALTER TABLE "LedgerEntry" ADD CONSTRAINT ledger_entry_amount_nonzero CHECK ("amountMinor" <> 0);
ALTER TABLE "LedgerEntry" ADD CONSTRAINT ledger_entry_currency_format CHECK ("currency" ~ '^[A-Z]{3}$');
ALTER TABLE "LedgerEntry" ADD CONSTRAINT ledger_entry_idempotency_key_present
  CHECK (length(btrim("idempotencyKey")) BETWEEN 1 AND 200);
-- Sign convention: money in and charges are positive, money out and costs negative, adjustments either way.
ALTER TABLE "LedgerEntry" ADD CONSTRAINT ledger_entry_sign_by_type CHECK (
  CASE "type"
    WHEN 'CHARGE' THEN "amountMinor" > 0
    WHEN 'PAYMENT' THEN "amountMinor" > 0
    WHEN 'REFUND' THEN "amountMinor" < 0
    WHEN 'CHARGEBACK' THEN "amountMinor" < 0
    WHEN 'MATERIAL_COST' THEN "amountMinor" < 0
    ELSE TRUE
  END
);
ALTER TABLE "LedgerEntry" ADD CONSTRAINT ledger_entry_reversal_link
  CHECK (("type" = 'REVERSAL') = ("reversesEntryId" IS NOT NULL) AND ("source" = 'REVERSAL') = ("type" = 'REVERSAL'));
ALTER TABLE "LedgerEntry" ADD CONSTRAINT ledger_entry_one_actor
  CHECK (("actorUserId" IS NOT NULL) <> ("systemActor" IS NOT NULL));
ALTER TABLE "LedgerEntry" ADD CONSTRAINT ledger_entry_system_actor_format
  CHECK ("systemActor" IS NULL OR "systemActor" ~ '^system:[a-z0-9][a-z0-9_.-]{0,62}$');
ALTER TABLE "LedgerEntry" ADD CONSTRAINT ledger_entry_subject
  CHECK ("jobId" IS NOT NULL OR "customerId" IS NOT NULL);
-- The source says which record produced the entry, and that record's reference must be present.
ALTER TABLE "LedgerEntry" ADD CONSTRAINT ledger_entry_source_matches_type CHECK (
  CASE "type"
    WHEN 'CHARGE' THEN "source" IN ('JOB', 'OUTCOME')
    WHEN 'PAYMENT' THEN "source" = 'PAYMENT'
    WHEN 'REFUND' THEN "source" = 'REFUND'
    WHEN 'CHARGEBACK' THEN "source" = 'CHARGEBACK'
    WHEN 'ADJUSTMENT' THEN "source" = 'ADJUSTMENT'
    WHEN 'MATERIAL_COST' THEN "source" = 'MATERIAL_USAGE'
    WHEN 'REVERSAL' THEN "source" = 'REVERSAL'
  END
);
ALTER TABLE "LedgerEntry" ADD CONSTRAINT ledger_entry_source_reference CHECK (
  CASE "source"
    WHEN 'JOB' THEN "jobId" IS NOT NULL
    WHEN 'OUTCOME' THEN "outcomeId" IS NOT NULL
    WHEN 'PAYMENT' THEN "paymentId" IS NOT NULL
    WHEN 'REFUND' THEN "refundId" IS NOT NULL
    WHEN 'CHARGEBACK' THEN "chargebackId" IS NOT NULL
    WHEN 'ADJUSTMENT' THEN "adjustmentId" IS NOT NULL
    WHEN 'MATERIAL_USAGE' THEN "materialUsageId" IS NOT NULL
    ELSE TRUE
  END
);

-- ───────────── Materials and cost versions ─────────────
ALTER TABLE "Material" ADD CONSTRAINT material_code_format CHECK ("code" ~ '^[a-z0-9][a-z0-9_.-]{0,62}$');
ALTER TABLE "Material" ADD CONSTRAINT material_name_present CHECK (length(btrim("name")) > 0);
ALTER TABLE "Material" ADD CONSTRAINT material_unit_present CHECK (length(btrim("unit")) > 0);

ALTER TABLE "MaterialCostVersion" ADD CONSTRAINT material_cost_version_number_positive CHECK ("versionNumber" > 0);
ALTER TABLE "MaterialCostVersion" ADD CONSTRAINT material_cost_version_cost_nonnegative CHECK ("unitCostMinor" >= 0);
ALTER TABLE "MaterialCostVersion" ADD CONSTRAINT material_cost_version_currency_format CHECK ("currency" ~ '^[A-Z]{3}$');
ALTER TABLE "MaterialCostVersion" ADD CONSTRAINT material_cost_version_period
  CHECK ("effectiveTo" IS NULL OR "effectiveTo" > "effectiveFrom");
ALTER TABLE "MaterialCostVersion" ADD CONSTRAINT material_cost_version_approved_at
  CHECK ("status" <> 'APPROVED' OR "approvedAt" IS NOT NULL);
-- Approved versions of one material never overlap in time (open-ended = until the next version closes it).
ALTER TABLE "MaterialCostVersion" ADD CONSTRAINT material_cost_version_no_overlap
  EXCLUDE USING gist (
    "tenantId" WITH =,
    "materialId" WITH =,
    tstzrange("effectiveFrom", COALESCE("effectiveTo", 'infinity'::timestamptz), '[)') WITH &&
  ) WHERE ("status" = 'APPROVED');

CREATE TRIGGER material_cost_version_status
  BEFORE UPDATE ON "MaterialCostVersion"
  FOR EACH ROW EXECUTE FUNCTION leadro_status_transitions(
    'PENDING_APPROVAL>APPROVED', 'PENDING_APPROVAL>REJECTED', 'PENDING_APPROVAL>CANCELLED');
CREATE TRIGGER material_cost_version_no_delete
  BEFORE DELETE ON "MaterialCostVersion"
  FOR EACH ROW EXECUTE FUNCTION leadro_no_delete();

-- What a cost version IS never changes (a different cost is a new version). Only `effectiveTo` may be set (once, from NULL,
-- to close the version), plus the approval bookkeeping (status, approvedAt, approvalRequestId, note).
CREATE OR REPLACE FUNCTION leadro_material_cost_version_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."materialId" <> OLD."materialId" OR NEW."versionNumber" <> OLD."versionNumber"
     OR NEW."unitCostMinor" <> OLD."unitCostMinor" OR NEW."currency" <> OLD."currency"
     OR NEW."effectiveFrom" <> OLD."effectiveFrom" OR NEW."createdById" IS DISTINCT FROM OLD."createdById"
     OR NEW."createdAt" <> OLD."createdAt" THEN
    RAISE EXCEPTION 'a material cost version is immutable: propose a new version instead' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD."effectiveTo" IS NOT NULL AND NEW."effectiveTo" IS DISTINCT FROM OLD."effectiveTo" THEN
    RAISE EXCEPTION 'a closed material cost version cannot be reopened or moved' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD."status" = 'APPROVED' AND (NEW."approvedAt" IS DISTINCT FROM OLD."approvedAt"
     OR NEW."approvalRequestId" IS DISTINCT FROM OLD."approvalRequestId") THEN
    RAISE EXCEPTION 'the approval of a cost version cannot be changed' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER material_cost_version_guard
  BEFORE UPDATE ON "MaterialCostVersion"
  FOR EACH ROW EXECUTE FUNCTION leadro_material_cost_version_guard();

-- Job material usage: the cost snapshot is all-or-nothing and, once taken, final (spec 11.4, 25.4).
ALTER TABLE "JobMaterialUsage" ADD CONSTRAINT job_material_usage_cost_snapshot CHECK (
  ("costVersionId" IS NULL AND "unitCostMinor" IS NULL AND "extendedCostMinor" IS NULL AND "costCurrency" IS NULL AND "costedAt" IS NULL)
  OR ("costVersionId" IS NOT NULL AND "materialId" IS NOT NULL AND "unitCostMinor" IS NOT NULL AND "extendedCostMinor" IS NOT NULL
      AND "costCurrency" IS NOT NULL AND "costedAt" IS NOT NULL)
);
ALTER TABLE "JobMaterialUsage" ADD CONSTRAINT job_material_usage_cost_nonnegative
  CHECK ("unitCostMinor" IS NULL OR ("unitCostMinor" >= 0 AND "extendedCostMinor" >= 0));
ALTER TABLE "JobMaterialUsage" ADD CONSTRAINT job_material_usage_cost_currency_format
  CHECK ("costCurrency" IS NULL OR "costCurrency" ~ '^[A-Z]{3}$');

CREATE OR REPLACE FUNCTION leadro_job_material_usage_cost_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF OLD."costVersionId" IS NOT NULL AND (
       NEW."costVersionId" IS DISTINCT FROM OLD."costVersionId" OR NEW."materialId" IS DISTINCT FROM OLD."materialId"
    OR NEW."unitCostMinor" IS DISTINCT FROM OLD."unitCostMinor" OR NEW."extendedCostMinor" IS DISTINCT FROM OLD."extendedCostMinor"
    OR NEW."costCurrency" IS DISTINCT FROM OLD."costCurrency" OR NEW."costedAt" IS DISTINCT FROM OLD."costedAt"
    OR NEW."quantity" <> OLD."quantity") THEN
    RAISE EXCEPTION 'a costed material usage is a snapshot and cannot change: record a correction instead' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER job_material_usage_cost_guard
  BEFORE UPDATE ON "JobMaterialUsage"
  FOR EACH ROW EXECUTE FUNCTION leadro_job_material_usage_cost_guard();

