ALTER TABLE "Payment" ADD CONSTRAINT payment_amount_positive CHECK ("amountMinor" > 0);
ALTER TABLE "Payment" ADD CONSTRAINT payment_currency_format CHECK ("currency" ~ '^[A-Z]{3}$');
ALTER TABLE "Payment" ADD CONSTRAINT payment_provider_pair CHECK (("provider" IS NULL) = ("providerRef" IS NULL));
ALTER TABLE "Payment" ADD CONSTRAINT payment_origin_fields CHECK (
  ("origin" = 'PROVIDER' AND "provider" IS NOT NULL AND "intakeEventId" IS NOT NULL)
  OR ("origin" = 'MANUAL' AND "recordedById" IS NOT NULL)
);
ALTER TABLE "Payment" ADD CONSTRAINT payment_received_at CHECK ("status" <> 'RECEIVED' OR "receivedAt" IS NOT NULL);
ALTER TABLE "Payment" ADD CONSTRAINT payment_failed_fields
  CHECK ("status" <> 'FAILED' OR ("failedAt" IS NOT NULL AND length(btrim(coalesce("failureReason", ''))) > 0));
ALTER TABLE "Payment" ADD CONSTRAINT payment_voided_fields
  CHECK ("status" <> 'VOIDED' OR ("voidedAt" IS NOT NULL AND length(btrim(coalesce("voidReason", ''))) > 0));
CREATE UNIQUE INDEX payment_provider_ref_unique
