CREATE TRIGGER payment_status
  BEFORE UPDATE ON "Payment"
  FOR EACH ROW EXECUTE FUNCTION leadro_status_transitions(
    'PENDING>RECEIVED', 'PENDING>FAILED', 'PENDING>VOIDED', 'RECEIVED>VOIDED');
CREATE TRIGGER payment_immutable
  BEFORE UPDATE ON "Payment"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns(
    'tenantId', 'jobId', 'amountMinor', 'currency', 'method', 'origin', 'provider', 'providerRef', 'intakeEventId', 'createdAt');
CREATE TRIGGER payment_no_delete BEFORE DELETE ON "Payment" FOR EACH ROW EXECUTE FUNCTION leadro_no_delete();

ALTER TABLE "Refund" ADD CONSTRAINT refund_amount_positive CHECK ("amountMinor" > 0);
ALTER TABLE "Refund" ADD CONSTRAINT refund_currency_format CHECK ("currency" ~ '^[A-Z]{3}$');
ALTER TABLE "Refund" ADD CONSTRAINT refund_reason_present CHECK (length(btrim("reason")) > 0);
ALTER TABLE "Refund" ADD CONSTRAINT refund_posted_at CHECK ("status" <> 'POSTED' OR "postedAt" IS NOT NULL);
ALTER TABLE "Refund" ADD CONSTRAINT refund_decided_at CHECK ("status" NOT IN ('APPROVED', 'REJECTED') OR "decidedAt" IS NOT NULL);
CREATE TRIGGER refund_status
  BEFORE UPDATE ON "Refund"
  FOR EACH ROW EXECUTE FUNCTION leadro_status_transitions(
    'REQUESTED>PENDING_APPROVAL', 'REQUESTED>APPROVED', 'REQUESTED>CANCELLED',
    'PENDING_APPROVAL>APPROVED', 'PENDING_APPROVAL>REJECTED', 'PENDING_APPROVAL>CANCELLED',
    'APPROVED>POSTED', 'APPROVED>CANCELLED');
CREATE TRIGGER refund_immutable
  BEFORE UPDATE ON "Refund"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns(
    'tenantId', 'jobId', 'paymentId', 'amountMinor', 'currency', 'reason', 'requestedById', 'requestedAt', 'createdAt');
CREATE TRIGGER refund_no_delete BEFORE DELETE ON "Refund" FOR EACH ROW EXECUTE FUNCTION leadro_no_delete();

ALTER TABLE "Chargeback" ADD CONSTRAINT chargeback_amount_positive CHECK ("amountMinor" > 0);
ALTER TABLE "Chargeback" ADD CONSTRAINT chargeback_currency_format CHECK ("currency" ~ '^[A-Z]{3}$');
ALTER TABLE "Chargeback" ADD CONSTRAINT chargeback_provider_pair CHECK (("provider" IS NULL) = ("providerRef" IS NULL));
ALTER TABLE "Chargeback" ADD CONSTRAINT chargeback_resolved_at
  CHECK ("status" NOT IN ('WON', 'LOST', 'WRITTEN_OFF') OR "resolvedAt" IS NOT NULL);
ALTER TABLE "Chargeback" ADD CONSTRAINT chargeback_write_off_needs_request
  CHECK ("status" <> 'WRITE_OFF_PENDING_APPROVAL' OR "writeOffApprovalRequestId" IS NOT NULL);
CREATE UNIQUE INDEX chargeback_provider_ref_unique
  ON "Chargeback" ("tenantId", "provider", "providerRef") WHERE "providerRef" IS NOT NULL;
CREATE TRIGGER chargeback_status
  BEFORE UPDATE ON "Chargeback"
  FOR EACH ROW EXECUTE FUNCTION leadro_status_transitions(
    'OPEN>DISPUTED', 'OPEN>WON', 'OPEN>LOST', 'DISPUTED>WON', 'DISPUTED>LOST',
    'LOST>WRITE_OFF_PENDING_APPROVAL', 'LOST>WRITTEN_OFF',
    'WRITE_OFF_PENDING_APPROVAL>WRITTEN_OFF', 'WRITE_OFF_PENDING_APPROVAL>LOST');
CREATE TRIGGER chargeback_immutable
  BEFORE UPDATE ON "Chargeback"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns(
    'tenantId', 'jobId', 'paymentId', 'amountMinor', 'currency', 'provider', 'providerRef', 'openedAt', 'createdAt');
CREATE TRIGGER chargeback_no_delete BEFORE DELETE ON "Chargeback" FOR EACH ROW EXECUTE FUNCTION leadro_no_delete();

ALTER TABLE "Adjustment" ADD CONSTRAINT adjustment_amount_nonzero CHECK ("amountMinor" <> 0);
ALTER TABLE "Adjustment" ADD CONSTRAINT adjustment_currency_format CHECK ("currency" ~ '^[A-Z]{3}$');
ALTER TABLE "Adjustment" ADD CONSTRAINT adjustment_reason_present CHECK (length(btrim("reason")) > 0);
ALTER TABLE "Adjustment" ADD CONSTRAINT adjustment_subject CHECK ("jobId" IS NOT NULL OR "customerId" IS NOT NULL);
ALTER TABLE "Adjustment" ADD CONSTRAINT adjustment_posted_at CHECK ("status" <> 'POSTED' OR "postedAt" IS NOT NULL);
ALTER TABLE "Adjustment" ADD CONSTRAINT adjustment_decided_at CHECK ("status" NOT IN ('APPROVED', 'REJECTED') OR "decidedAt" IS NOT NULL);
