  BEFORE UPDATE ON "Adjustment"
  FOR EACH ROW EXECUTE FUNCTION leadro_status_transitions(
    'PENDING_APPROVAL>APPROVED', 'PENDING_APPROVAL>REJECTED', 'PENDING_APPROVAL>CANCELLED',
    'APPROVED>POSTED', 'APPROVED>CANCELLED');
CREATE TRIGGER adjustment_immutable
  BEFORE UPDATE ON "Adjustment"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns(
    'tenantId', 'jobId', 'customerId', 'outcomeId', 'amountMinor', 'currency', 'reason', 'requestedById', 'requestedAt', 'createdAt');
CREATE TRIGGER adjustment_no_delete BEFORE DELETE ON "Adjustment" FOR EACH ROW EXECUTE FUNCTION leadro_no_delete();

-- ───────────── Approvals ─────────────
ALTER TABLE "ApprovalPolicy" ADD CONSTRAINT approval_policy_code_format CHECK ("code" ~ '^[a-z0-9][a-z0-9_.-]{0,62}$');
ALTER TABLE "ApprovalPolicy" ADD CONSTRAINT approval_policy_name_present CHECK (length(btrim("name")) > 0);
ALTER TABLE "ApprovalPolicy" ADD CONSTRAINT approval_policy_version_positive CHECK ("version" > 0);
ALTER TABLE "ApprovalPolicy" ADD CONSTRAINT approval_policy_required_approvals CHECK ("requiredApprovals" IN (1, 2));
ALTER TABLE "ApprovalPolicy" ADD CONSTRAINT approval_policy_currency_format CHECK ("currency" ~ '^[A-Z]{3}$');
ALTER TABLE "ApprovalPolicy" ADD CONSTRAINT approval_policy_threshold_range
  CHECK ("minAmountMinor" >= 0 AND ("maxAmountMinor" IS NULL OR "maxAmountMinor" > "minAmountMinor"));
ALTER TABLE "ApprovalPolicy" ADD CONSTRAINT approval_policy_approver_permission_format
  CHECK ("approverPermission" ~ '^[a-z][a-z0-9_]*\.[a-z][a-z_]*$');
ALTER TABLE "ApprovalPolicy" ADD CONSTRAINT approval_policy_expiry_positive
  CHECK ("expiresAfterHours" IS NULL OR "expiresAfterHours" > 0);
-- One active version per policy code.
CREATE UNIQUE INDEX approval_policy_one_active_version
  ON "ApprovalPolicy" ("tenantId", "code") WHERE "active";
-- A policy's content never changes (a new version is a new row); only `active` (and updatedAt) may.
CREATE TRIGGER approval_policy_guard
  BEFORE UPDATE ON "ApprovalPolicy"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns(
    'tenantId', 'code', 'subjectType', 'name', 'version', 'currency', 'minAmountMinor', 'maxAmountMinor',
    'requiredApprovals', 'approverPermission', 'expiresAfterHours', 'createdAt');
CREATE TRIGGER approval_policy_no_delete BEFORE DELETE ON "ApprovalPolicy" FOR EACH ROW EXECUTE FUNCTION leadro_no_delete();

ALTER TABLE "ApprovalRequest" ADD CONSTRAINT approval_request_required_approvals CHECK ("requiredApprovals" IN (1, 2));
ALTER TABLE "ApprovalRequest" ADD CONSTRAINT approval_request_amount_pair
  CHECK (("amountMinor" IS NULL) = ("currency" IS NULL) AND ("amountMinor" IS NULL OR "amountMinor" >= 0));
ALTER TABLE "ApprovalRequest" ADD CONSTRAINT approval_request_currency_format
  CHECK ("currency" IS NULL OR "currency" ~ '^[A-Z]{3}$');
ALTER TABLE "ApprovalRequest" ADD CONSTRAINT approval_request_decided_at
  CHECK ("status" NOT IN ('APPROVED', 'REJECTED') OR "decidedAt" IS NOT NULL);
ALTER TABLE "ApprovalRequest" ADD CONSTRAINT approval_request_cancelled_fields
  CHECK ("status" <> 'CANCELLED' OR ("cancelledAt" IS NOT NULL AND length(btrim(coalesce("cancelReason", ''))) > 0));
-- One open request per subject at a time.
CREATE UNIQUE INDEX approval_request_one_pending_per_subject
  ON "ApprovalRequest" ("tenantId", "subjectType", "subjectId") WHERE "status" = 'PENDING';
CREATE TRIGGER approval_request_status
  BEFORE UPDATE ON "ApprovalRequest"
  FOR EACH ROW EXECUTE FUNCTION leadro_status_transitions(
    'PENDING>APPROVED', 'PENDING>REJECTED', 'PENDING>CANCELLED', 'PENDING>EXPIRED');
-- The policy snapshot, subject and the people who may not decide it are fixed when the request is made.
CREATE TRIGGER approval_request_immutable
  BEFORE UPDATE ON "ApprovalRequest"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns(
    'tenantId', 'subjectType', 'subjectId', 'policyId', 'policyCode', 'policyVersion', 'requiredApprovals',
    'approverPermission', 'amountMinor', 'currency', 'requestedById', 'excludedApproverIds', 'requestedAt', 'expiresAt', 'createdAt');
CREATE TRIGGER approval_request_no_delete BEFORE DELETE ON "ApprovalRequest" FOR EACH ROW EXECUTE FUNCTION leadro_no_delete();

-- Separation of duties at the last line of defense (spec 21.3): the requester and the people who edited or submitted the
-- subject can never decide it, and nobody decides a request that is no longer pending.
CREATE OR REPLACE FUNCTION leadro_approval_decision_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  req "ApprovalRequest"%ROWTYPE;
BEGIN
  SELECT * INTO req FROM "ApprovalRequest" WHERE "id" = NEW."requestId" AND "tenantId" = NEW."tenantId";
  IF NOT FOUND THEN
    RAISE EXCEPTION 'approval request % does not exist', NEW."requestId" USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF req."status" <> 'PENDING' THEN
    RAISE EXCEPTION 'approval request % is not pending', req."id" USING ERRCODE = 'restrict_violation';
  END IF;
  IF req."requestedById" IS NOT DISTINCT FROM NEW."deciderId" OR NEW."deciderId" = ANY (req."excludedApproverIds") THEN
    RAISE EXCEPTION 'separation of duties: the requester or an editor of the subject cannot decide it' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER approval_decision_guard
  BEFORE INSERT ON "ApprovalDecision"
  FOR EACH ROW EXECUTE FUNCTION leadro_approval_decision_guard();

-- ───────────── Reconciliation ─────────────
ALTER TABLE "ReconciliationRun" ADD CONSTRAINT reconciliation_run_currency_format CHECK ("currency" ~ '^[A-Z]{3}$');
ALTER TABLE "ReconciliationRun" ADD CONSTRAINT reconciliation_run_period CHECK ("periodEnd" > "periodStart");
ALTER TABLE "ReconciliationRun" ADD CONSTRAINT reconciliation_run_counts CHECK ("jobsExamined" >= 0 AND "exceptionCount" >= 0);
ALTER TABLE "ReconciliationRun" ADD CONSTRAINT reconciliation_run_completed_at
  CHECK ("status" <> 'COMPLETED' OR "completedAt" IS NOT NULL);
CREATE TRIGGER reconciliation_run_status
  BEFORE UPDATE ON "ReconciliationRun"
  FOR EACH ROW EXECUTE FUNCTION leadro_status_transitions('RUNNING>COMPLETED', 'RUNNING>FAILED');
CREATE TRIGGER reconciliation_run_immutable
  BEFORE UPDATE ON "ReconciliationRun"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns('tenantId', 'legalEntityId', 'currency', 'periodStart', 'periodEnd', 'startedAt');
CREATE TRIGGER reconciliation_run_no_delete BEFORE DELETE ON "ReconciliationRun" FOR EACH ROW EXECUTE FUNCTION leadro_no_delete();

ALTER TABLE "ReconciliationException" ADD CONSTRAINT reconciliation_exception_currency_format CHECK ("currency" ~ '^[A-Z]{3}$');
ALTER TABLE "ReconciliationException" ADD CONSTRAINT reconciliation_exception_assigned
  CHECK ("status" <> 'ASSIGNED' OR ("assignedToId" IS NOT NULL AND "assignedAt" IS NOT NULL));
ALTER TABLE "ReconciliationException" ADD CONSTRAINT reconciliation_exception_resolved CHECK (
  "status" <> 'RESOLVED'
  OR ("resolvedAt" IS NOT NULL AND "resolvedById" IS NOT NULL AND length(btrim(coalesce("resolutionReason", ''))) > 0)
);
CREATE TRIGGER reconciliation_exception_status
  BEFORE UPDATE ON "ReconciliationException"
  FOR EACH ROW EXECUTE FUNCTION leadro_status_transitions('OPEN>ASSIGNED', 'OPEN>RESOLVED', 'ASSIGNED>OPEN', 'ASSIGNED>RESOLVED');
CREATE TRIGGER reconciliation_exception_immutable
  BEFORE UPDATE ON "ReconciliationException"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns(
    'tenantId', 'runId', 'kind', 'jobId', 'paymentId', 'intakeEventId', 'currency', 'expectedAmountMinor', 'recordedAmountMinor', 'createdAt');
CREATE TRIGGER reconciliation_exception_no_delete BEFORE DELETE ON "ReconciliationException" FOR EACH ROW EXECUTE FUNCTION leadro_no_delete();

-- ───────────── External payment intake log ─────────────
ALTER TABLE "PaymentIntakeEvent" ADD CONSTRAINT payment_intake_event_hash_format CHECK ("payloadHash" ~ '^[0-9a-f]{64}$');
ALTER TABLE "PaymentIntakeEvent" ADD CONSTRAINT payment_intake_event_identity_present
  CHECK (length(btrim("provider")) > 0 AND length(btrim("externalId")) > 0 AND length(btrim("eventType")) > 0);
ALTER TABLE "PaymentIntakeEvent" ADD CONSTRAINT payment_intake_event_currency_format
  CHECK ("currency" IS NULL OR "currency" ~ '^[A-Z]{3}$');
ALTER TABLE "PaymentIntakeEvent" ADD CONSTRAINT payment_intake_event_amount_positive
  CHECK ("amountMinor" IS NULL OR "amountMinor" > 0);
-- An event whose signature did not verify can only ever be REJECTED (or still RECEIVED while being validated).
ALTER TABLE "PaymentIntakeEvent" ADD CONSTRAINT payment_intake_event_signature_gate
  CHECK ("signatureValid" OR "status" IN ('RECEIVED', 'REJECTED'));
ALTER TABLE "PaymentIntakeEvent" ADD CONSTRAINT payment_intake_event_rejection_code
  CHECK ("status" NOT IN ('REJECTED', 'UNMATCHED') OR length(btrim(coalesce("rejectionCode", ''))) > 0);
CREATE TRIGGER payment_intake_event_status
  BEFORE UPDATE ON "PaymentIntakeEvent"
  FOR EACH ROW EXECUTE FUNCTION leadro_status_transitions(
    'RECEIVED>ACCEPTED', 'RECEIVED>REJECTED', 'RECEIVED>DUPLICATE', 'RECEIVED>UNMATCHED', 'UNMATCHED>ACCEPTED');
CREATE TRIGGER payment_intake_event_immutable
  BEFORE UPDATE ON "PaymentIntakeEvent"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns(
    'tenantId', 'provider', 'externalId', 'eventType', 'payloadHash', 'signatureValid', 'receivedAt');
CREATE TRIGGER payment_intake_event_no_delete BEFORE DELETE ON "PaymentIntakeEvent" FOR EACH ROW EXECUTE FUNCTION leadro_no_delete();
